<div wire:poll.5s class="panel table-wrap"><table><thead><tr><th>File</th><th>Uploaded by</th><th>Size</th><th>Status</th><th></th></tr></thead><tbody>@forelse($assets as $asset)<tr wire:key="asset-{{ $asset->id }}"><td><strong>{{ $asset->name }}</strong>@if($asset->error)<small class="danger">{{ $asset->error }}</small>@endif</td><td>{{ $asset->uploader->name }}</td><td>{{ $asset->size ? number_format($asset->size/1024).' KB':'Link' }}</td><td><span class="badge {{ $asset->status }}">{{ ucfirst($asset->status) }}</span></td><td>@if($asset->url && $asset->status==='ready')<a href="{{ $asset->url }}" target="_blank" rel="noopener">Open ↗</a>@elseif($asset->status==='failed')<small>Upload this file again to retry.</small>@endif</td></tr>@empty<tr><td colspan="5" class="empty">Your project’s files will live here.</td></tr>@endforelse</tbody></table></div>
